/* Load any uncompiled macros specific to this analysis            */
%afi_caf_loadmacros(/Products/SAS Analytics For IoT/CustomAnalyses/Launch/macros);


/* PREPROCESS to prepare for analysis work                         */
%afi_caf_preprocess(?g_cas, ?analysisID);


CAS qasout SESSOPTS=(CASLIB=QASANLOUT) ;
libname qasout CAS sessref=qasout;
caslib _all_ assign;


option mprint; 
%macro ingest_data;



    data work.analysis_data; 
		format datetime datetime21.; 
        set &g_p_caslib..&g_p_tablenm.; 
		datetime = dhms(mdy(1,1,1970),0,0, msr_timestamp/1000000);
		drop opcode key1 key2 flags msr_timestamp;
		Where assetID="Inverter_A";
    run; 


    /* Prep Metadata for dropdown */

/* Asset List */
proc sql; 
	create table assetList as 
		select distinct(assetID) as assetID
from work.analysis_data; 
quit;


/* Target & Input Variables */

proc contents data=work.analysis_data out=work.contents noprint ; 
run;

proc sql noprint; 
	create table work.varList as 
		select distinct(name) as VAR_COLUMN_NAME
		from work.contents 
		where name not in ( "assetID", "assetType", "datetime"); 
quit;

data _null_;
	set assetList end=end;
	count+1;
 	call symputx("assetID"||left(count),assetID);
	if end then call symputx('assetCnt',count);
run; 

%put &&assetID1; 
%do i=1 %to &assetCnt.;

data assetMetadata_&i.;
format  ASSET_ID ASSET_ID_DESC TAG_ID TAG_ID_DESC $32.;
	set work.varList ; 
	ASSET_ID="&&assetID&i."; 
	ASSET_ID_DESC="&&assetID&i."; 
	TAG_ID=VAR_COLUMN_NAME; 
	TAG_ID_DESC="&&assetID&i."||"."||VAR_COLUMN_NAME; 
keep ASSET_ID ASSET_ID_DESC TAG_ID TAG_ID_DESC; 

run; 

%end;

data assetTagList; 
	set %do i=1 %to &assetCnt.;
		assetMetadata_&i.
		%end;;
run; 

%mend;

%ingest_data;

/* To finish the analysis specific code, setup the info needed for */
/* the postprocess.                                                */

/* Provide any output tables to be persisted and used later.       */
/* Postprocess will promote and save the output tables in the      */
/* QASANLOUT global caslib using a standard naming convention of   */
/* <analysis_type>_tablename_<shortid>                             */
/* For example: CARS_filtered_ABC123                               */
/*              CARS_complete_ABC123                               */
%let g_num_output_tables = 4;
%let g_output_table_1 = work.analysis_data;
%let g_output_table_2 = work.assetList;
%let g_output_table_3 = work.varList;
%let g_output_table_4 = work.assetTagList;



/* Provide any output variable to be used later.                   */
/* Postprocess will save these variables into metadata so they can */
/* be used in the VA output or in later analysis steps             */
/* For example: filtered_count = 20                                */
%let g_num_output_vars = 1;
%let g_output_var_1 = &g_p_tablenm.;

/* *************************************************************** */
/* END ANALYSIS SPECIFIC PROGRAMMING                               */
/* *************************************************************** */



/* PREPROCESS to save analysis work                                */
%afi_caf_postprocess;

/* Load any uncompiled macros specific to this analysis            */
%afi_caf_loadmacros(/Products/SAS Analytics For IoT/CustomAnalyses/Launch/macros);


/* PREPROCESS to prepare for analysis work                         */
%afi_caf_preprocess(?g_cas, ?analysisID);


CAS qasout SESSOPTS=(CASLIB=QASANLOUT) ;
libname qasout CAS sessref=qasout;
caslib _all_ assign;


option mprint; 

/* Create Filters for Data */


%put &=G_STABLE_PERIOD.;
%global /* G_STABLESTART G_STABLEEND*/ G_TIME_FILTER;

%macro generate_time_filter;

  %local i G_STABLE_PART G_STABLESTART G_STABLEEND;
  %let i = 1;
  %let G_TIME_FILTER =;

  %let G_STABLE_PERIOD = %sysfunc(strip(&G_STABLE_PERIOD.));
  %let G_STABLE_PART = %scan(%nrbquote(&G_STABLE_PERIOD.), &i., ','); 

  %do %until (%length(&G_STABLE_PART.) = 0); 
    %let G_STABLESTART = %scan(%nrbquote(&G_STABLE_PART.), 1, '-');
    %let G_STABLEEND = %scan(%nrbquote(&G_STABLE_PART.), 2, '-');

    %if &i. eq 1 %then %do;
      %let G_TIME_FILTER = (DATETIME le "&G_STABLESTART."dt or DATETIME ge "&G_STABLEEND."dt);
    %end;
    %else %do;
      %let G_TIME_FILTER = &G_TIME_FILTER. and (DATETIME le "&G_STABLESTART."dt or DATETIME ge "&G_STABLEEND."dt);
    %end;

    %put &=i. &=G_STABLE_PART. &=G_STABLESTART. &=G_STABLEEND.;

    %let i = %eval(&i. + 1);
    %let G_STABLE_PART = %scan(%nrbquote(&G_STABLE_PERIOD.), &i., ','); 
  %end;
  %let G_TIME_FILTER=(&G_TIME_FILTER.);
%mend generate_time_filter;
%generate_time_filter;
%put &=G_TIME_FILTER.;

/* Train Model */

%put &=g_p_inputvar; 

data qasout.modeldata; 
  set qasout.&g_analysis_type._analysis_data_&g_short_id.;
  where  &G_TIME_FILTER.; 
run;

%let varlist_new = %sysfunc(tranwrd(%quote(&g_p_inputvar), %str(,), %str( )));

ods output FitStatistics=FitStatistics ParameterEstimates=ParameterEstimates;
proc glm data = qasout.modeldata;;
  model &g_p_target.=&varlist_new. / solution; 
run;  

data FitStat; 
  set FitStatistics; 
run; 

data ParamEst; 
  format Parameter $32.;
  set ParameterEstimates; 
run; 

/** Forest Teast for registering model in MM */
proc partition data=qasout.modeldata samppct=70 seed=123 partind;
   output out=qasout.modeldata2 ;
/*   display 'SRSFreq';*/
run;
proc forest data = qasout.modeldata2;
	id assetID; 
  	input &varlist_new.  /level=interval; 
	target  CURRENT_THISINVERTER /level=interval;
	partition rolevar=_PartIND_(train='0' validate='1');
	savestate rstore=qasout.saveFOREST_caf; 
	output out=qasout.outForest copyvars=(_ALL_); 
run;  

proc astore ; 
ods select StoreKey InputVariables OutputVariables;
		   ods output StoreKey=astorekey; 
		   ods output InputVariables=work.astoreInputVariables; 
		   ods output OutputVariables=work.astoreOutputVariables; 
	describe rstore= qasout.saveFOREST_caf; 
quit; 

proc astore;
   download rstore = qasout.saveFOREST_caf
            store = "/export/sas-viya/homes/prshar/Common_Data/CAF_Demo/astore/saveFOREST_caf.sasast";
run;

proc registermodel
      name = "Forest Astore"
      description = "Forest Astore Model"
      data = qasout.modeldata2
      algorithm = Forest
      function = PREDICTION
      replace;
   project name="solarFarm_caf" folder="test_caf";
   astoremodel store = "/export/sas-viya/homes/prshar/Common_Data/CAF_Demo/astore/saveFOREST_caf.sasast";
   target CURRENT_THISINVERTER /level=interval;
   assessment;
run;

/* To finish the analysis specific code, setup the info needed for */
/* the postprocess.                                                */

/* Provide any output tables to be persisted and used later.       */
/* Postprocess will promote and save the output tables in the      */
/* QASANLOUT global caslib using a standard naming convention of   */
/* <analysis_type>_tablename_<shortid>                             */
/* For example: CARS_filtered_ABC123                               */
/*              CARS_complete_ABC123                               */

%let g_num_output_tables = 2;

%let g_output_table_1 = work.FitStat;
%let g_output_table_2 = work.ParamEst;



/* Provide any output variable to be used later.                   */
/* Postprocess will save these variables into metadata so they can */
/* be used in the VA output or in later analysis steps             */
/* For example: filtered_count = 20                                */
%let g_num_output_vars = 1;
%let g_output_var_1 = &varlist_new.;

/* *************************************************************** */
/* END ANALYSIS SPECIFIC PROGRAMMING                               */
/* *************************************************************** */



/* PREPROCESS to save analysis work                                */
%afi_caf_postprocess;
